// Expect: msg.payload = JSON telemetry dari MQTT (MCU)
// Topic contoh: esp32/<device>/telemetry
const p = msg.payload || {};
const topic = String(msg.topic || "");
const devFromTopic = (() => {
    const m = topic.match(/^esp32\/([^/]+)\//);
    return m ? m[1] : undefined;
})();
const device = String(p.device || devFromTopic || "unknown");

// ---- Timestamp ns (prioritas ts dari payload / millis MCU) ----
function toNs(ts) {
    if (typeof ts !== "number" || Number.isNaN(ts)) return Date.now() * 1e6;
    // heuristik: kalau ts >= 1e12 anggap ms, kalau >=1e9 anggap detik
    if (ts >= 1e12) return Math.floor(ts * 1e6); // ms -> ns
    if (ts >= 1e9) return Math.floor(ts * 1e9); //  s -> ns
    return Date.now() * 1e6;
}
const tsns = toNs(p.ts);

// ---- Escapers untuk line protocol ----
const esc = {
    meas: v => String(v).replace(/[, ]/g, "\\$&"),
    tag: v => String(v).replace(/[,= ]/g, "\\$&"),
    str: v => String(v).replace(/"/g, '\\"'),
};

// ---- Field formatters (tetap & konsisten tipe) ----
// float (default 0.0 kalau null/invalid)
function fkvFloat(k, v) {
    const n = (typeof v === "number" && Number.isFinite(v)) ? v : 0.0;
    return `${k}=${n}`;
}
// integer (default 0i)
function fkvInt(k, v) {
    const n = (typeof v === "number" && Number.isFinite(v)) ? Math.trunc(v) : 0;
    return `${k}=${n}i`;
}
// boolean (default false)
function fkvBool(k, v) {
    return `${k}=${!!v}`;
}
// string (kalau mau simpan string sebagai field)
function fkvStr(k, v) {
    return `${k}="${esc.str(v)}"`;
}

const lines = [];

// ============== sensors[] ==============
// t & h selalu FLOAT; kalau null → 0.0 (biar nggak konflik tipe)
if (Array.isArray(p.sensors)) {
    for (const s of p.sensors) {
        const sid = s && s.id ? String(s.id) : "unknown";
        const fields = [
            fkvFloat("t", s?.t),
            fkvFloat("h", s?.h),
        ];
        lines.push(
            `sensor,device=${esc.tag(device)},sensor_id=${esc.tag(sid)},topic=${esc.tag(topic || "telemetry")} ${fields.join(",")} ${tsns}`
        );
    }
}

// ============== lamps[] ==============
// power: INTEGER 0/1; kalau null → 0i
if (Array.isArray(p.lamps)) {
    for (const l of p.lamps) {
        const lid = l && l.id ? String(l.id) : "unknown";
        const fields = [fkvInt("power", l?.power)];
        lines.push(
            `lamp,device=${esc.tag(device)},lamp_id=${esc.tag(lid)},topic=${esc.tag(topic || "telemetry")} ${fields.join(",")} ${tsns}`
        );
    }
}

// ============== telemetry (summary) ==============
// power_master: BOOL
// dht_setpoint: INTEGER (ikut skema sebelumnya)
// hard_min/max/hyst: FLOAT (disimpan juga buat audit config terbaru)
{
    const cfg = p.config || p.option || {}; // MCU kirim di "config", fallback "option"
    const fields = [
        fkvBool("power_master", p.power_master),
        fkvInt("dht_setpoint", cfg.dht_setpoint ?? cfg.setpoint),
        fkvFloat("hard_min", cfg.hard_min),
        fkvFloat("hard_max", cfg.hard_max),
        fkvFloat("hyst", cfg.hyst),
        // kalau mau simpan last_updated string juga:
        // (comment kalau nggak perlu)
        // p.last_updated ? fkvStr("last_updated", String(p.last_updated)) : null,
    ].filter(Boolean);

    lines.push(
        `telemetry,device=${esc.tag(device)},topic=${esc.tag(topic || "telemetry")} ${fields.join(",")} ${tsns}`
    );
}

// ============== HTTP Write ke InfluxDB ==============
msg.headers = {
    Authorization: "Token " + (flow.get("INFLUX_TOKEN") || "REPLACE_TOKEN"),
    "Content-Type": "text/plain",
};

// org/bucket dari flow context .env
const org = encodeURIComponent(flow.get("INFLUX_ORG") || "REPLACE_ORG");
const bucket = encodeURIComponent(flow.get("INFLUX_BUCKET") || "REPLACE_BUCKET");
msg.url = `http://influxdb:8086/api/v2/write?org=${org}&bucket=${bucket}&precision=ns`;

// gabung semua line protocol
msg.payload = lines.join("\n");
return msg;

