// ===== Heartbeat → Line Protocol (InfluxDB v2) =====
// Expect: msg.payload = JSON heartbeat dari MQTT:
// { device:"doc-kandang-01", ts:107605602, uptime_s:107605, last_updated:"2025-09-29T15:00:44+0700",
//   wifi:{ ssid:"Annura", ip:"192.168.100.80", rssi:-69 },
//   sys:{ heap_free:198428, cpu_mhz:240, temp_c:62.77 }, fw:"1.0.0", claimed:false }

const p = msg.payload || {};
const topic = msg.topic || "";
const devFromTopic = (() => { const m = topic.match(/^esp32\/([^/]+)\//); return m ? m[1] : undefined; })();
const device = p.device || devFromTopic || "unknown";

// === Timestamp ns ===
function toNsFromHeartbeat(obj) {
    if (typeof obj.ts === 'number' && Number.isFinite(obj.ts)) {
        if (obj.ts >= 1e12) return Math.floor(obj.ts * 1e6); // ms -> ns
        if (obj.ts >= 1e9) return Math.floor(obj.ts * 1e9); // s  -> ns
    }
    if (obj.last_updated) {
        const d = Date.parse(obj.last_updated);
        if (!Number.isNaN(d)) return d * 1e6; // ms -> ns
    }
    return Date.now() * 1e6;
}
const tsns = toNsFromHeartbeat(p);

// === Escapers & builders ===
const esc = {
    meas: v => String(v).replace(/[, ]/g, "\\$&"),
    tag: v => String(v).replace(/[,= ]/g, "\\$&"),
    str: v => String(v).replace(/"/g, '\\"'),
};
const fStr = (k, v) => (v === undefined || v === null) ? null : `${k}="${esc.str(String(v))}"`;
const fFlt = (k, v, def = null) => {
    const num = Number(v);
    if (!Number.isFinite(num)) return def === null ? null : `${k}=${def}`;
    return `${k}=${num}`;
};
const fInt = (k, v, def = null) => {
    const num = Number(v);
    if (!Number.isFinite(num)) return def === null ? null : `${k}=${Math.trunc(def)}i`;
    return `${k}=${Math.trunc(num)}i`;
};

// === Collect fields (CONSISTENT TYPES) ===
// top-level
const fields = [
    fInt('ts', p.ts),               // device timestamp (int)
    fInt('uptime_s', p.uptime_s),         // int
    fStr('last_updated', p.last_updated),     // string RFC3339
    fStr('fw', p.fw),               // string
    (typeof p.claimed === 'boolean') ? `claimed=${p.claimed}` : null, // bool
    // wifi.*
    fStr('wifi_ssid', p?.wifi?.ssid),
    fStr('wifi_ip', p?.wifi?.ip),
    fInt('wifi_rssi', p?.wifi?.rssi),
    // sys.*
    fInt('sys_heap_free', p?.sys?.heap_free),
    fInt('sys_cpu_mhz', p?.sys?.cpu_mhz),
    fFlt('sys_temp_c', p?.sys?.temp_c, 0.0),
].filter(Boolean);

// === Line protocol ===
// TAGS: hanya device (hindari tag high-cardinality seperti ssid/fw)
const line = `heartbeat,device=${esc.tag(device)} ${fields.join(',')} ${tsns}`;

// === HTTP write ===
msg.headers = {
    'Authorization': 'Token ' + (flow.get('INFLUX_TOKEN') || 'REPLACE_TOKEN'),
    'Content-Type': 'text/plain'
};
msg.url = `http://influxdb:8086/api/v2/write?org=${encodeURIComponent(flow.get('INFLUX_ORG') || 'REPLACE_ORG')}&bucket=${encodeURIComponent(flow.get('INFLUX_BUCKET') || 'REPLACE_BUCKET')}&precision=ns`;
msg.payload = line;
return msg;

