// ===== Device State → InfluxDB v2 Line Protocol =====
// Expect: msg.payload = { state: "online"/"offline" }
// or msg.topic = "esp32/<device>/state"

const p = msg.payload || {};
const topic = msg.topic || "";
const m = topic.match(/^esp32\/([^/]+)\//);
const device = m ? m[1] : (p.device || "unknown");

// === Normalize state ===
const stateStr = String(p.state || "unknown").toLowerCase();
const stateNum = stateStr === "online" ? 1 : 0;

// === Timestamp (ns) ===
const tsns = Date.now() * 1e6;

// === Escape helpers ===
const esc = {
  meas: v => String(v).replace(/[, ]/g, "\\$&"),
  tag: v => String(v).replace(/[,= ]/g, "\\$&"),
  str: v => String(v).replace(/"/g, '\\"')
};

// === Build line protocol ===
// Measurement: device_state
// Tags: device
// Fields: state (string), state_num (int)
const fields = [
  `state="${esc.str(stateStr)}"`,
  `state_num=${stateNum}i`
];
const line = `device_state,device=${esc.tag(device)} ${fields.join(",")} ${tsns}`;

// === HTTP Write Config (same style as heartbeat) ===
msg.headers = {
  "Authorization": "Token " + (flow.get("INFLUX_TOKEN") || "REPLACE_TOKEN"),
  "Content-Type": "text/plain"
};
msg.url = `http://influxdb:8086/api/v2/write?org=${encodeURIComponent(flow.get("INFLUX_ORG") || "REPLACE_ORG")}&bucket=${encodeURIComponent(flow.get("INFLUX_BUCKET") || "REPLACE_BUCKET")}&precision=ns`;
msg.payload = line;
msg.method = "POST";
msg.return = "full";

// Optional debug
// node.warn({ line });

return msg;

const p = msg.payload;
const cfg = p.config || {};
const sensors = p.sensors || [];

// Calculate avg temp (only valid sensors: >10 and <60)
const temps = sensors
  .map(s => s.t)
  .filter(t => typeof t === 'number' && t > 10 && t < 60);

if (temps.length === 0) return null;

const avgTemp = temps.reduce((a, b) => a + b, 0) / temps.length;
const setpoint = cfg.dht_setpoint || 34;

// Cooldown: only alert once per drop (5 min)
const lastAlert = flow.get('lastTempAlert') || 0;
const now = Date.now();
const COOLDOWN_MS = 5 * 60 * 1000;

if (avgTemp < setpoint && (now - lastAlert) > COOLDOWN_MS) {
  flow.set('lastTempAlert', now);

  // Send via Laravel API → FCM v1
  const fcmTopic = 'iot_' + (p.device || 'unknown').replace(/[^a-zA-Z0-9_-]/g, '_');

  msg.payload = {
    topic: fcmTopic,
    title: '⚠️ Suhu Rendah!',
    body: 'Rata-rata ' + avgTemp.toFixed(1) + '°C, target ' + setpoint + '°C',
    data: {
      type: 'temp_alert',
      avg_temp: String(avgTemp.toFixed(1)),
      setpoint: String(setpoint)
    }
  };
  msg.headers = {
    'Content-Type': 'application/json'
  };
  msg.url = flow.get('API_BASE') + '/api/fcm/send';
  return msg;
}

// Reset cooldown when temp goes back above setpoint
if (avgTemp >= setpoint) {
  flow.set('lastTempAlert', 0);
}
return null;
